class Solution {
public:
    int maxCollectedFruits(vector<vector<int>>& fruits) {
        int n = fruits.size();
        int child1 = 0;
        for (int i = 0; i < n; ++i) child1 += fruits[i][i];

        auto collectUpper = [&](const vector<vector<int>>& grid) {
            vector<vector<int>> dp(n, vector<int>(n, -1));
            dp[0][n - 1] = grid[0][n - 1];
            for (int r = 0; r < n - 1; ++r) {
                for (int c = r + 1; c < n; ++c) {
                    if (dp[r][c] == -1) continue;
                    for (int nc : {c - 1, c, c + 1}) {
                        if (nc > r + 1 && nc < n && nc >= n - 1 - (r + 1)) {
                            dp[r + 1][nc] = max(dp[r + 1][nc], dp[r][c] + grid[r + 1][nc]);
                        } else if (r + 1 == n - 1 && nc == n - 1) {
                            dp[r + 1][nc] = max(dp[r + 1][nc], dp[r][c] + grid[r + 1][nc]);
                        }
                    }
                }
            }
            return dp[n - 1][n - 1];
        };

        int child2 = collectUpper(fruits);
        vector<vector<int>> transposed(n, vector<int>(n));
        for (int r = 0; r < n; ++r)
            for (int c = 0; c < n; ++c)
                transposed[r][c] = fruits[c][r];
        int child3 = collectUpper(transposed);

        return child1 + child2 + child3 - 2 * fruits[n - 1][n - 1];
    }
};

class Solution {
    public int maxCollectedFruits(int[][] fruits) {
        int n = fruits.length;
        int child1 = 0;
        for (int i = 0; i < n; ++i) child1 += fruits[i][i];

        int child2 = collectUpper(fruits);
        int[][] transposed = new int[n][n];
        for (int r = 0; r < n; ++r)
            for (int c = 0; c < n; ++c)
                transposed[r][c] = fruits[c][r];
        int child3 = collectUpper(transposed);

        return child1 + child2 + child3 - 2 * fruits[n - 1][n - 1];
    }

    private int collectUpper(int[][] grid) {
        int n = grid.length;
        int[][] dp = new int[n][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        dp[0][n - 1] = grid[0][n - 1];

        for (int r = 0; r < n - 1; ++r) {
            for (int c = r + 1; c < n; ++c) {
                if (dp[r][c] == -1) continue;
                for (int nc : new int[]{c - 1, c, c + 1}) {
                    if (nc > r + 1 && nc < n && nc >= n - 1 - (r + 1)) {
                        dp[r + 1][nc] = Math.max(dp[r + 1][nc], dp[r][c] + grid[r + 1][nc]);
                    } else if (r + 1 == n - 1 && nc == n - 1) {
                        dp[r + 1][nc] = Math.max(dp[r + 1][nc], dp[r][c] + grid[r + 1][nc]);
                    }
                }
            }
        }
        return dp[n - 1][n - 1];
    }
}

