    const collectUpper = (grid) => {
        const dp = Array.from({ length: n }, () => Array(n).fill(-1));
        dp[0][n - 1] = grid[0][n - 1];
        for (let r = 0; r < n - 1; r++) {
            for (let c = r + 1; c < n; c++) {
                if (dp[r][c] === -1) continue;
                for (const nc of [c - 1, c, c + 1]) {
